import fs from 'node:fs';
import assert from 'node:assert/strict';
import {sha256,validateTracker} from './scripts/remediation/board.mjs';
const startedAt=new Date().toISOString();
const path='docs/remediation/evidence/W04.01/tracker-before-v1.json';
const priorBytes=fs.readFileSync(path);
assert.equal(sha256(priorBytes),'922c1a207b8e8d4c7fae6ab3342a0680eb64af04d5eea984d19bcdd2dd5d1cfc');
const currentBytes=fs.readFileSync('docs/remediation/tracker.json');
