NODE

closureSanity.command:
node --input-type=module <<'NODE'
import fs from 'node:fs';
import assert from 'node:assert/strict';
import {sha256,artifactDigest,taskContractDigest} from './scripts/remediation/board.mjs';
const t=JSON.parse(fs.readFileSync('docs/remediation/tracker.json'));
const w=t.tasks.find(x=>x.id==='W04.01');
assert.equal(t.journal.at(-1).seq,189);
assert.equal(w.state,'closed');
assert.equal(w.independent_review.status,'accepted');
assert.equal(w.lead_signoff.status,'accepted');
assert.equal(w.handoff.status,'complete');
assert.equal(w.lead_signoff.review_sha256,sha256(JSON.stringify(w.independent_review)));
assert.equal(w.preflight.contract_digest,taskContractDigest(w));
assert.equal(w.artifact.digest,artifactDigest(w.artifact));
for(const c of w.checks){assert.equal(c.result,'pass');assert.equal(c.evidence_ids.length,1);}
for(const e of t.evidence.filter(e=>e.task_id==='W04.01')){assert.equal(e.status,'current');assert.deepEqual(e.artifact_basis,w.artifact);assert.equal(sha256(fs.readFileSync(e.file.path)),e.file.sha256);}
for(const f of w.artifact.files)assert.equal(sha256(fs.readFileSync(f.path)),f.sha256,f.path);
for(const v of [w.independent_review.record,w.lead_signoff.record])assert.equal(sha256(fs.readFileSync(v.path)),v.sha256,v.path);
const previousBytes=fs.readFileSync('docs/remediation/evidence/W04.01/tracker-before-v1.json');
assert.equal(sha256(previousBytes),'922c1a207b8e8d4c7fae6ab3342a0680eb64af04d5eea984d19bcdd2dd5d1cfc');
const previous=JSON.parse(previousBytes);
assert.deepEqual(t.journal.slice(0,177),previous.journal);
assert.equal(t.resume.journal_seq,189);
assert.equal(t.tasks.filter(x=>['in_progress','verification'].includes(x.state)).length,0);
console.log(JSON.stringify({state:w.state,seq:189,pins:w.artifact.files.length,artifact:w.artifact.digest,trackerSha256:sha256(fs.readFileSync('docs/remediation/tracker.json')),trustedBeforeSha256:sha256(previousBytes),currentEvidence:2,priorJournalPrefixUnchanged:true,note:'Cheap actual-disk closure sanity, not substitute for required board/append-only validators.'}));
NODE
